const normalizeOfficialPokemonName = (name) => String(name || '').normalize('NFKC').replace(/\s+/g, '').replace(/[・·]/g, '').toLowerCase()

const OFFICIAL_POKEMON_NAME_BY_NORMALIZED_NAME = Object.fromEntries(
  Object.keys(OFFICIAL_LEVEL_UP_LEARNSETS_BY_POKEMON_NAME).map((name) => [normalizeOfficialPokemonName(name), name])
)

export const getOfficialPokemonNameKey = (monster) => OFFICIAL_POKEMON_NAME_BY_NORMALIZED_NAME[normalizeOfficialPokemonName(monster?.name)] || null

export const getOfficialLearnLevelByMove = (monster) => {
  const nameKey = getOfficialPokemonNameKey(monster)
  return nameKey ? (OFFICIAL_LEVEL_UP_LEARNSETS_BY_POKEMON_NAME[nameKey] || {}) : {}
}

export const getOfficialLearnsetVersionGroup = (monster) => {
  const nameKey = getOfficialPokemonNameKey(monster)
  return nameKey ? (OFFICIAL_LEARNSET_VERSION_GROUP_BY_POKEMON_NAME[nameKey] || null) : null
}
